using var adapter = new LabScriptedAdapter();
using var c = new LabController(adapter);
string id = c.Submit("QueryState", 0);
adapter.Emit(new LabCompletion(id, c.Session, "Completed"));
var audio = new LabAudioPath { Capturing=false, SendingAttached=true, ReceivingAttached=true, SpeakerConnected=true };
Console.WriteLine($"control={c.Results[id]} tx={audio.Tx} rx={audio.Rx}"); // Completed False True
audio.Capturing=true; // 測試注入來源恢復
Console.WriteLine($"tx={audio.Tx} rx={audio.Rx}"); // True True

var path = new LabAudioPath { Capturing=true, SendingAttached=true, ReceivingAttached=true, SpeakerConnected=true };
var a = path;
var b = path;
a.Capturing=false;
Console.WriteLine(ReferenceEquals(a,b)); // True
Console.WriteLine(b.Tx); // False
var independent = new LabAudioPath { Capturing=true, SendingAttached=true, ReceivingAttached=true, SpeakerConnected=true };
a.Capturing=false;
Console.WriteLine(independent.Tx); // True
